import { getDatabase } from './index.js';
import { randomUUID } from 'crypto';

export interface Session {
  id: string;
  title: string;
  customTitle: string | null;
  summary: string | null;
  createdAt: string;
  updatedAt: string;
  messageCount: number;
  projectPath: string | null;
  sourceFile: string | null;
  rawData: string;
  isSidechain: boolean;
  isAutomated: boolean;
}

export interface Message {
  id: number;
  sessionId: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
}

export interface SessionInput {
  title: string;
  summary?: string;
  projectPath?: string;
  sourceFile?: string;
  rawData: string;
  messages: Omit<Message, 'id' | 'sessionId'>[];
  isSidechain?: boolean;
  isAutomated?: boolean;
}

export interface EmbeddingState {
  sessionId: string;
  contentLength: number;
  fileMtime: string | null;
  lastEmbeddedAt: string;
}

/**
 * Create a new session
 */
export function createSession(input: SessionInput): string {
  const db = getDatabase();
  const id = randomUUID();
  const now = new Date().toISOString();

  const insertSession = db.prepare(`
    INSERT INTO sessions (id, title, summary, created_at, updated_at, message_count, project_path, source_file, raw_data, is_sidechain, is_automated)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const insertMessage = db.prepare(`
    INSERT INTO messages (session_id, role, content, timestamp)
    VALUES (?, ?, ?, ?)
  `);

  const transaction = db.transaction(() => {
    insertSession.run(
      id,
      input.title,
      input.summary || null,
      now,
      now,
      input.messages.length,
      input.projectPath || null,
      input.sourceFile || null,
      input.rawData,
      input.isSidechain ? 1 : 0,
      input.isAutomated ? 1 : 0
    );

    for (const msg of input.messages) {
      insertMessage.run(id, msg.role, msg.content, msg.timestamp);
    }
  });

  transaction();
  return id;
}

/**
 * Update an existing session with new data
 */
export function updateSession(id: string, input: Partial<SessionInput>): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  const updates: string[] = ['updated_at = ?'];
  const values: unknown[] = [now];

  if (input.title !== undefined) {
    updates.push('title = ?');
    values.push(input.title);
  }
  if (input.summary !== undefined) {
    updates.push('summary = ?');
    values.push(input.summary);
  }
  if (input.rawData !== undefined) {
    updates.push('raw_data = ?');
    values.push(input.rawData);
  }
  if (input.messages !== undefined) {
    updates.push('message_count = ?');
    values.push(input.messages.length);
  }
  if (input.isSidechain !== undefined) {
    updates.push('is_sidechain = ?');
    values.push(input.isSidechain ? 1 : 0);
  }
  if (input.isAutomated !== undefined) {
    updates.push('is_automated = ?');
    values.push(input.isAutomated ? 1 : 0);
  }
  if (input.projectPath !== undefined) {
    updates.push('project_path = ?');
    values.push(input.projectPath);
  }

  values.push(id);

  const transaction = db.transaction(() => {
    db.prepare(`UPDATE sessions SET ${updates.join(', ')} WHERE id = ?`).run(...values);

    // If messages provided, replace them
    if (input.messages !== undefined) {
      db.prepare('DELETE FROM messages WHERE session_id = ?').run(id);
      const insertMessage = db.prepare(`
        INSERT INTO messages (session_id, role, content, timestamp)
        VALUES (?, ?, ?, ?)
      `);
      for (const msg of input.messages) {
        insertMessage.run(id, msg.role, msg.content, msg.timestamp);
      }
    }
  });

  transaction();
}

/**
 * Get a session by ID
 */
export function getSession(id: string): Session | null {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT id, title, custom_title as customTitle, summary,
           created_at as createdAt, updated_at as updatedAt,
           message_count as messageCount, project_path as projectPath,
           source_file as sourceFile, raw_data as rawData,
           is_sidechain as isSidechain, is_automated as isAutomated
    FROM sessions WHERE id = ?
  `).get(id) as SessionRow | undefined;

  if (!row) return null;
  return mapSessionRow(row);
}

/**
 * Get a session by ID prefix (for partial ID matching)
 */
export function getSessionByIdPrefix(idPrefix: string): Session | null {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT id, title, custom_title as customTitle, summary,
           created_at as createdAt, updated_at as updatedAt,
           message_count as messageCount, project_path as projectPath,
           source_file as sourceFile, raw_data as rawData,
           is_sidechain as isSidechain, is_automated as isAutomated
    FROM sessions WHERE id LIKE ? || '%'
    LIMIT 1
  `).get(idPrefix) as SessionRow | undefined;

  if (!row) return null;
  return mapSessionRow(row);
}

/**
 * Get a session by source file path
 */
export function getSessionBySourceFile(sourceFile: string): Session | null {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT id, title, custom_title as customTitle, summary,
           created_at as createdAt, updated_at as updatedAt,
           message_count as messageCount, project_path as projectPath,
           source_file as sourceFile, raw_data as rawData,
           is_sidechain as isSidechain, is_automated as isAutomated
    FROM sessions WHERE source_file = ?
  `).get(sourceFile) as SessionRow | undefined;

  if (!row) return null;
  return mapSessionRow(row);
}

/**
 * Get messages for a session
 */
export function getSessionMessages(sessionId: string): Message[] {
  const db = getDatabase();
  const rows = db.prepare(`
    SELECT id, session_id as sessionId, role, content, timestamp
    FROM messages WHERE session_id = ?
    ORDER BY timestamp ASC
  `).all(sessionId) as Message[];

  return rows;
}

type SessionRow = {
  isSidechain: number;
  isAutomated: number;
  customTitle: string | null;
} & Omit<Session, 'isSidechain' | 'isAutomated' | 'customTitle'>;

function mapSessionRow(row: SessionRow): Session {
  return {
    ...row,
    customTitle: row.customTitle,
    isSidechain: row.isSidechain === 1,
    isAutomated: row.isAutomated === 1,
  };
}

/**
 * List all sessions ordered by updated_at desc
 */
export function listSessions(limit = 100): Session[] {
  const db = getDatabase();
  const rows = db.prepare(`
    SELECT id, title, custom_title as customTitle, summary,
           created_at as createdAt, updated_at as updatedAt,
           message_count as messageCount, project_path as projectPath,
           source_file as sourceFile, raw_data as rawData,
           is_sidechain as isSidechain, is_automated as isAutomated
    FROM sessions
    ORDER BY updated_at DESC
    LIMIT ?
  `).all(limit) as SessionRow[];

  return rows.map(mapSessionRow);
}

/**
 * Check if a session appears to be an automated/system session rather than a real human conversation
 * Uses metadata stored in the database (isSidechain, isAutomated) which was extracted from the JSONL
 */
export function isAutomatedSession(session: Session): boolean {
  // Use the metadata fields from the database
  if (session.isSidechain || session.isAutomated) {
    return true;
  }

  return false;
}

/**
 * List human sessions (filters out automated/system sessions)
 * Filters directly in SQL for better performance
 */
export function listHumanSessions(limit = 100): Session[] {
  const db = getDatabase();
  const rows = db.prepare(`
    SELECT id, title, custom_title as customTitle, summary,
           created_at as createdAt, updated_at as updatedAt,
           message_count as messageCount, project_path as projectPath,
           source_file as sourceFile, raw_data as rawData,
           is_sidechain as isSidechain, is_automated as isAutomated
    FROM sessions
    WHERE is_sidechain = 0 AND is_automated = 0
    ORDER BY updated_at DESC
    LIMIT ?
  `).all(limit) as SessionRow[];

  return rows.map(mapSessionRow);
}

/**
 * List human sessions filtered by project path
 * Uses LIKE to match sessions where the project_path starts with the given path
 */
export function listHumanSessionsByProject(projectPath: string, limit = 100): Session[] {
  const db = getDatabase();
  // Use LIKE to match sessions in this folder or subfolders
  const rows = db.prepare(`
    SELECT id, title, custom_title as customTitle, summary,
           created_at as createdAt, updated_at as updatedAt,
           message_count as messageCount, project_path as projectPath,
           source_file as sourceFile, raw_data as rawData,
           is_sidechain as isSidechain, is_automated as isAutomated
    FROM sessions
    WHERE is_sidechain = 0 AND is_automated = 0
      AND project_path LIKE ? || '%'
    ORDER BY updated_at DESC
    LIMIT ?
  `).all(projectPath, limit) as SessionRow[];

  return rows.map(mapSessionRow);
}

/**
 * Delete a session
 */
export function deleteSession(id: string): boolean {
  const db = getDatabase();

  const transaction = db.transaction(() => {
    // Delete from vector table first
    db.prepare('DELETE FROM session_embeddings WHERE session_id = ?').run(id);
    // Delete embedding state
    db.prepare('DELETE FROM embedding_state WHERE session_id = ?').run(id);
    // Delete messages (cascade should handle this, but explicit is safer)
    db.prepare('DELETE FROM messages WHERE session_id = ?').run(id);
    // Delete session
    const result = db.prepare('DELETE FROM sessions WHERE id = ?').run(id);
    return result.changes > 0;
  });

  return transaction();
}

/**
 * Update session summary
 */
export function updateSessionSummary(id: string, summary: string): void {
  const db = getDatabase();
  db.prepare(`
    UPDATE sessions SET summary = ?, updated_at = ? WHERE id = ?
  `).run(summary, new Date().toISOString(), id);
}

/**
 * Rename a session (set custom title)
 */
export function renameSession(id: string, customTitle: string | null): void {
  const db = getDatabase();
  db.prepare(`
    UPDATE sessions SET custom_title = ?, updated_at = ? WHERE id = ?
  `).run(customTitle, new Date().toISOString(), id);
}

/**
 * Get storage statistics
 */
export function getStats(): {
  sessionCount: number;
  messageCount: number;
  embeddingCount: number;
} {
  const db = getDatabase();

  const sessionCount = (db.prepare('SELECT COUNT(*) as count FROM sessions').get() as { count: number }).count;
  const messageCount = (db.prepare('SELECT COUNT(*) as count FROM messages').get() as { count: number }).count;
  const embeddingCount = (db.prepare('SELECT COUNT(*) as count FROM session_embeddings').get() as { count: number }).count;

  return { sessionCount, messageCount, embeddingCount };
}

/**
 * Check if a session exists by its raw data hash (to avoid duplicates)
 */
export function sessionExists(rawData: string): boolean {
  const db = getDatabase();
  const row = db.prepare('SELECT 1 FROM sessions WHERE raw_data = ? LIMIT 1').get(rawData);
  return !!row;
}

/**
 * Get embedding state for a session
 */
export function getEmbeddingState(sessionId: string): EmbeddingState | null {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT session_id as sessionId, content_length as contentLength,
           file_mtime as fileMtime, last_embedded_at as lastEmbeddedAt
    FROM embedding_state WHERE session_id = ?
  `).get(sessionId) as EmbeddingState | undefined;

  return row || null;
}

/**
 * Update embedding state for a session
 */
export function updateEmbeddingState(
  sessionId: string,
  contentLength: number,
  fileMtime?: string
): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  db.prepare(`
    INSERT OR REPLACE INTO embedding_state (session_id, content_length, file_mtime, last_embedded_at)
    VALUES (?, ?, ?, ?)
  `).run(sessionId, contentLength, fileMtime || null, now);
}

/**
 * Check if session needs re-embedding based on content growth
 * Returns true if content has grown by more than threshold chars
 */
export function needsReembedding(sessionId: string, currentContentLength: number, threshold = 500): boolean {
  const state = getEmbeddingState(sessionId);
  if (!state) return true; // Never embedded
  return currentContentLength - state.contentLength >= threshold;
}

/**
 * Get all sessions that need embedding
 */
export function getSessionsNeedingEmbedding(): Session[] {
  const db = getDatabase();
  const rows = db.prepare(`
    SELECT s.id, s.title, s.custom_title as customTitle, s.summary,
           s.created_at as createdAt, s.updated_at as updatedAt,
           s.message_count as messageCount, s.project_path as projectPath,
           s.source_file as sourceFile, s.raw_data as rawData,
           s.is_sidechain as isSidechain, s.is_automated as isAutomated
    FROM sessions s
    LEFT JOIN embedding_state e ON s.id = e.session_id
    WHERE e.session_id IS NULL
    ORDER BY s.updated_at DESC
  `).all() as SessionRow[];

  return rows.map(mapSessionRow);
}

// ==================== FAVORITES ====================

export type FavoriteType = 'session' | 'folder';

export interface Favorite {
  id: number;
  type: FavoriteType;
  value: string;
  createdAt: string;
}

/**
 * Add a favorite (session or folder)
 */
export function addFavorite(type: FavoriteType, value: string): boolean {
  const db = getDatabase();
  try {
    db.prepare(`
      INSERT OR IGNORE INTO favorites (type, value, created_at)
      VALUES (?, ?, ?)
    `).run(type, value, new Date().toISOString());
    return true;
  } catch {
    return false;
  }
}

/**
 * Remove a favorite
 */
export function removeFavorite(type: FavoriteType, value: string): boolean {
  const db = getDatabase();
  const result = db.prepare(`
    DELETE FROM favorites WHERE type = ? AND value = ?
  `).run(type, value);
  return result.changes > 0;
}

/**
 * Toggle a favorite (add if not exists, remove if exists)
 */
export function toggleFavorite(type: FavoriteType, value: string): boolean {
  if (isFavorite(type, value)) {
    removeFavorite(type, value);
    return false; // No longer a favorite
  } else {
    addFavorite(type, value);
    return true; // Now a favorite
  }
}

/**
 * Check if something is a favorite
 */
export function isFavorite(type: FavoriteType, value: string): boolean {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT 1 FROM favorites WHERE type = ? AND value = ?
  `).get(type, value);
  return !!row;
}

/**
 * Get all favorites of a type
 */
export function getFavorites(type: FavoriteType): Favorite[] {
  const db = getDatabase();
  const rows = db.prepare(`
    SELECT id, type, value, created_at as createdAt
    FROM favorites
    WHERE type = ?
    ORDER BY created_at DESC
  `).all(type) as Favorite[];
  return rows;
}

/**
 * Get all favorite session IDs
 */
export function getFavoriteSessionIds(): Set<string> {
  const favorites = getFavorites('session');
  return new Set(favorites.map(f => f.value));
}

/**
 * Get all favorite folder paths
 */
export function getFavoriteFolderPaths(): Set<string> {
  const favorites = getFavorites('folder');
  return new Set(favorites.map(f => f.value));
}

/**
 * Check if there are any favorite folders
 */
export function hasFavoriteFolders(): boolean {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT 1 FROM favorites WHERE type = 'folder' LIMIT 1
  `).get();
  return !!row;
}

/**
 * Check if there are any favorite sessions
 */
export function hasFavoriteSessions(): boolean {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT 1 FROM favorites WHERE type = 'session' LIMIT 1
  `).get();
  return !!row;
}

// ==================== PROJECT ORDER ====================

export interface ProjectOrder {
  path: string;
  sortOrder: number;
  updatedAt: string;
}

/**
 * Get the sort order for all projects
 * Returns a map of project path -> sort order
 */
export function getProjectOrders(): Map<string, number> {
  const db = getDatabase();
  const rows = db.prepare(`
    SELECT path, sort_order as sortOrder
    FROM project_order
    ORDER BY sort_order ASC
  `).all() as { path: string; sortOrder: number }[];

  const map = new Map<string, number>();
  for (const row of rows) {
    map.set(row.path, row.sortOrder);
  }
  return map;
}

/**
 * Set the sort order for a project
 */
export function setProjectOrder(path: string, sortOrder: number): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  db.prepare(`
    INSERT OR REPLACE INTO project_order (path, sort_order, updated_at)
    VALUES (?, ?, ?)
  `).run(path, sortOrder, now);
}

/**
 * Update project orders for multiple projects at once (for reordering)
 */
export function updateProjectOrders(orders: { path: string; sortOrder: number }[]): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  const stmt = db.prepare(`
    INSERT OR REPLACE INTO project_order (path, sort_order, updated_at)
    VALUES (?, ?, ?)
  `);

  const transaction = db.transaction(() => {
    for (const order of orders) {
      stmt.run(order.path, order.sortOrder, now);
    }
  });

  transaction();
}

/**
 * Remove project order (revert to default sorting for this project)
 */
export function removeProjectOrder(path: string): void {
  const db = getDatabase();
  db.prepare('DELETE FROM project_order WHERE path = ?').run(path);
}

/**
 * Check if any custom project orders exist
 */
export function hasCustomProjectOrder(): boolean {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT 1 FROM project_order LIMIT 1
  `).get();
  return !!row;
}
