import { readFileSync, readdirSync, existsSync, statSync } from 'fs';
import { join, basename, dirname } from 'path';
import { CLAUDE_PROJECTS_DIR, CLAUDE_SESSIONS_DIR } from '../utils/config.js';

export interface ParsedMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
}

export interface SessionMetadata {
  isSidechain: boolean;
  isMeta: boolean;
}

// Patterns that indicate automated/system sessions based on title
const AUTOMATED_TITLE_PATTERNS = [
  /^<[a-z-]+>/i,           // XML-like tags: <project-instructions>, <command-message>, etc.
  /^<[A-Z_]+>/,            // Uppercase tags: <SYSTEM>, <TOOL_USE>, etc.
  /^\[system\]/i,          // [system] prefix
  /^\/[a-z]+$/i,           // Slash commands: /init, /help, etc.
];

/**
 * Check if a title/first message indicates an automated session
 */
export function isAutomatedByContent(title: string): boolean {
  for (const pattern of AUTOMATED_TITLE_PATTERNS) {
    if (pattern.test(title.trim())) {
      return true;
    }
  }
  return false;
}

export interface ParsedSession {
  filePath: string;
  projectPath: string | null;
  messages: ParsedMessage[];
  rawData: string;
  modifiedAt: Date;
  agentMessages?: ParsedMessage[]; // Messages from subagents linked to this session
}

interface SessionIndexEntry {
  sessionId: string;
  fullPath: string;
  fileMtime: number;
  firstPrompt: string;
  messageCount: number;
  created: string;
  modified: string;
  gitBranch?: string;
  projectPath: string;
  isSidechain: boolean;
}

interface SessionsIndex {
  version: number;
  entries: SessionIndexEntry[];
}

/**
 * Extract session metadata from JSONL file (isSidechain, agentId, isMeta, etc.)
 * Only uses reliable JSONL metadata fields, not content-based heuristics
 */
export function extractSessionMetadata(filepath: string): SessionMetadata {
  const content = readFileSync(filepath, 'utf-8');

  const metadata: SessionMetadata = {
    isSidechain: false,
    isMeta: false,
  };

  // Find the first user message to check metadata
  for (const line of content.split('\n')) {
    if (!line.trim()) continue;

    try {
      const parsed = JSON.parse(line);

      // Look for the first user message
      if (parsed.type === 'user' && parsed.message) {
        // Check isSidechain field (present in all Claude Code JSONL entries)
        // This is true for subagent/automated sessions
        if (parsed.isSidechain === true) {
          metadata.isSidechain = true;
        }

        // Check if this has an agentId (subagent session)
        if (parsed.agentId) {
          metadata.isSidechain = true;
        }

        // Check isMeta field - true for local command sessions
        if (parsed.isMeta === true) {
          metadata.isMeta = true;
        }

        break; // Only need first user message
      }
    } catch {
      // Skip malformed lines
    }
  }

  return metadata;
}

/**
 * Parse a Claude Code session JSONL file
 */
export function parseSessionFile(filepath: string): ParsedMessage[] {
  const content = readFileSync(filepath, 'utf-8');
  const messages: ParsedMessage[] = [];

  for (const line of content.split('\n')) {
    if (!line.trim()) continue;

    try {
      const parsed = JSON.parse(line);

      // Handle different Claude Code JSONL formats
      if ((parsed.type === 'user' || parsed.type === 'assistant') && parsed.message) {
        // Claude Code format: type is 'user'/'assistant', message contains the actual content
        const msg = parsed.message;
        if (msg.role && msg.content) {
          const content = Array.isArray(msg.content)
            ? msg.content
                .filter((c: { type: string }) => c.type === 'text')
                .map((c: { text: string }) => c.text)
                .join('\n')
            : typeof msg.content === 'string'
              ? msg.content
              : JSON.stringify(msg.content);

          if (content) {
            messages.push({
              role: msg.role as 'user' | 'assistant',
              content,
              timestamp: parsed.timestamp || new Date().toISOString(),
            });
          }
        }
      } else if (parsed.type === 'message' && parsed.role && parsed.content) {
        // Standard message format
        messages.push({
          role: parsed.role as 'user' | 'assistant',
          content: typeof parsed.content === 'string'
            ? parsed.content
            : JSON.stringify(parsed.content),
          timestamp: parsed.timestamp || new Date().toISOString(),
        });
      } else if (parsed.role && parsed.content && !parsed.type) {
        // Simplified format without type field
        messages.push({
          role: parsed.role as 'user' | 'assistant',
          content: typeof parsed.content === 'string'
            ? parsed.content
            : JSON.stringify(parsed.content),
          timestamp: parsed.timestamp || new Date().toISOString(),
        });
      }
      // Skip tool_use, tool_result, and other non-message entries
    } catch {
      // Skip malformed lines
    }
  }

  return messages;
}

/**
 * Find all Claude Code session files (excluding subagent sessions)
 */
export function findSessionFiles(): ParsedSession[] {
  const sessions: ParsedSession[] = [];

  // Search in ~/.claude/projects/<hash>/
  if (existsSync(CLAUDE_PROJECTS_DIR)) {
    const projectDirs = readdirSync(CLAUDE_PROJECTS_DIR);
    for (const projectDir of projectDirs) {
      const projectDirPath = join(CLAUDE_PROJECTS_DIR, projectDir);
      const stat = statSync(projectDirPath);
      if (!stat.isDirectory()) continue;

      // Try to read sessions-index.json for metadata
      const indexPath = join(projectDirPath, 'sessions-index.json');
      const sessionIndex = loadSessionIndex(indexPath);

      // Build a map of session IDs to their metadata
      const indexedSessions = new Map<string, SessionIndexEntry>();
      if (sessionIndex) {
        for (const entry of sessionIndex.entries) {
          indexedSessions.set(entry.sessionId, entry);
        }
      }

      // Only load .jsonl files directly in the project directory (not in subfolders)
      const entries = readdirSync(projectDirPath, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isFile() || !entry.name.endsWith('.jsonl')) continue;

        const filePath = join(projectDirPath, entry.name);
        const sessionId = entry.name.replace('.jsonl', '');

        try {
          const session = loadSession(filePath);
          if (session) {
            // Use metadata from sessions-index.json if available
            const indexEntry = indexedSessions.get(sessionId);
            if (indexEntry) {
              session.projectPath = indexEntry.projectPath;
            }

            // Load any subagent messages for this session
            const agentMessages = loadSubagentMessages(projectDirPath, sessionId);
            if (agentMessages.length > 0) {
              session.agentMessages = agentMessages;
            }

            sessions.push(session);
          }
        } catch {
          // Skip unreadable files
        }
      }
    }
  }

  // Search in ~/.claude/sessions/ (no subagents here)
  if (existsSync(CLAUDE_SESSIONS_DIR)) {
    const sessionFiles = readdirSync(CLAUDE_SESSIONS_DIR).filter(f => f.endsWith('.jsonl'));
    for (const sessionFile of sessionFiles) {
      const filePath = join(CLAUDE_SESSIONS_DIR, sessionFile);
      try {
        const session = loadSession(filePath);
        if (session) {
          sessions.push(session);
        }
      } catch {
        // Skip unreadable files
      }
    }
  }

  // Sort by modification time (newest first)
  sessions.sort((a, b) => b.modifiedAt.getTime() - a.modifiedAt.getTime());

  return sessions;
}

/**
 * Load sessions-index.json if it exists
 */
function loadSessionIndex(indexPath: string): SessionsIndex | null {
  if (!existsSync(indexPath)) return null;

  try {
    const content = readFileSync(indexPath, 'utf-8');
    return JSON.parse(content) as SessionsIndex;
  } catch {
    return null;
  }
}

/**
 * Load messages from all subagent sessions for a parent session
 */
function loadSubagentMessages(projectDirPath: string, parentSessionId: string): ParsedMessage[] {
  const subagentsDir = join(projectDirPath, parentSessionId, 'subagents');
  if (!existsSync(subagentsDir)) return [];

  const messages: ParsedMessage[] = [];

  try {
    const agentFiles = readdirSync(subagentsDir).filter(f => f.endsWith('.jsonl'));
    for (const agentFile of agentFiles) {
      const agentPath = join(subagentsDir, agentFile);
      const agentMessages = parseSessionFile(agentPath);
      messages.push(...agentMessages);
    }
  } catch {
    // Ignore errors reading subagent files
  }

  return messages;
}

/**
 * Load a session from a file path
 */
function loadSession(filePath: string): ParsedSession | null {
  const rawData = readFileSync(filePath, 'utf-8');
  const messages = parseSessionFile(filePath);

  // Skip empty sessions
  if (messages.length === 0) {
    return null;
  }

  const stats = statSync(filePath);

  return {
    filePath,
    projectPath: null,
    messages,
    rawData,
    modifiedAt: stats.mtime,
  };
}


/**
 * Get the most recent session file
 */
export function getMostRecentSession(): ParsedSession | null {
  const sessions = findSessionFiles();
  return sessions.length > 0 ? sessions[0] : null;
}

/**
 * Generate a summary from session messages
 */
export function generateSummary(messages: ParsedMessage[]): string {
  // Take first user message as the main topic
  const firstUserMessage = messages.find(m => m.role === 'user');
  if (!firstUserMessage) {
    return 'No user messages found';
  }

  // Truncate to reasonable summary length
  const summary = firstUserMessage.content.slice(0, 300);
  return summary.length < firstUserMessage.content.length ? summary + '...' : summary;
}
